const dayMs = 86400000;
const now = new Date();
const today = Math.floor(now.getTime() / dayMs);
const day = (index) => new Date(index * dayMs).toISOString().slice(0, 10);
const suppliers = ['Aster Components', 'Fieldstone Packaging', 'Northline Parts', 'Cedar Materials'];
const warehouses = ['Mumbai', 'Pune', 'Bengaluru'];
const skus = ['BX-110', 'BX-120', 'FT-205', 'FT-210', 'PK-320', 'PK-330', 'MT-440', 'MT-450'];

const orders = [];
for (let due = today - 44; due <= today + 6; due += 1) {
  for (let line = 1; line <= 6; line += 1) {
    const key = due * 997 + line * 317;
    const outcome = (key * 97) % 101;
    const completion = outcome < 76 ? due - key % 3 : due + 1 + key % 9;
    const cancelled = outcome >= 98;
    const closed = !cancelled && completion <= today;
    const ordered = 35 + key % 116;
    orders.push({
      order_id: `PO-${day(due)}`,
      line_number: line,
      supplier: suppliers[(due + line) % suppliers.length],
      warehouse: warehouses[(due + line) % warehouses.length],
      sku: skus[(key + line) % skus.length],
      ordered_qty: ordered,
      received_qty: closed ? ordered : cancelled ? 0 : Math.floor(ordered * (key % 3) / 4),
      promised_date: day(due),
      completed_date: closed ? day(completion) : null,
      cancelled,
    });
  }
}

const quarterHour = Math.floor(now.getTime() / 900000);
const inventory = warehouses.flatMap((warehouse, wh) => skus.map((sku, index) => ({
  warehouse,
  sku,
  on_hand_qty: (wh * 43 + index * 19 + quarterHour * 7) % 130,
  reorder_point: 24 + index % 4 * 5,
})));

return [{ json: {
  source_label: 'Generated records',
  source_as_of: now.toISOString(),
  orders,
  inventory,
} }];
